class TestRequirementsTheOutcomeChannelCannotSee:
    """Scored here, because no f2p/n2p test observes them.

    These are the whole reason the deterministic channel exists: a run can
    satisfy every target test and still miss all of them.
    """

    def test_s1_changed(self, report, record_property):
        'The reference change to reflex/components/tags/iter_tag.py is present. Any edit that achieves the same observable behaviour satisfies this.'
        c = _record(report, record_property, 'E2-req:S1-changed')
        assert c.weight > 0, "an unobserved requirement must be scored"

    def test_s2_removed(self, report, record_property):
        'The reference change to reflex/utils/build.py is a removal, so the check asserts the removed code is not reinstated.'
        c = _record(report, record_property, 'E2-req:S2-removed')
        assert c.weight > 0, "an unobserved requirement must be scored"

    def test_s4_changed(self, report, record_property):
        'The reference change to reflex/components/datadisplay/table.py is present. Any edit that achieves the same observable behaviour satisfies this.'
        c = _record(report, record_property, 'E2-req:S4-changed')
        assert c.weight > 0, "an unobserved requirement must be scored"

    def test_s5_removed(self, report, record_property):
        'The reference change to reflex/app.py is a removal, so the check asserts the removed code is not reinstated.'
        c = _record(report, record_property, 'E2-req:S5-removed')
        assert c.weight > 0, "an unobserved requirement must be scored"

    def test_s6_touched(self, report, record_property):
        'reflex/constants.py is edited. No stable text probe could be derived from the reference hunks for this file.'
        c = _record(report, record_property, 'E2-req:S6-touched')
        assert c.weight > 0, "an unobserved requirement must be scored"

    def test_s7_changed(self, report, record_property):
        'The reference change to reflex/model.py is present. Any edit that achieves the same observable behaviour satisfies this.'
        c = _record(report, record_property, 'E2-req:S7-changed')
        assert c.weight > 0, "an unobserved requirement must be scored"

    def test_s8_touched(self, report, record_property):
        'pyproject.toml is edited. No stable text probe could be derived from the reference hunks for this file.'
        c = _record(report, record_property, 'E2-req:S8-touched')
        assert c.weight > 0, "an unobserved requirement must be scored"


class TestRequirementsAlreadyPricedByTheOutcomeChannel:
    """Recorded only. `continuous_score_v2` already scores these through the
    f2p tests, so weighting them here would pay for one fact twice.
    """

    def test_s3_changed_is_recorded_not_scored(self, report, record_property):
        'The reference change to reflex/config.py is present. Any edit that achieves the same observable behaviour satisfies this.'
        c = _record(report, record_property, 'E2-req:S3-changed')
        assert 0 < c.weight < REQUIREMENT_WEIGHT, (
            "already priced by the outcome channel, so discounted here; "
            "zero would lose the gradient entirely")


class TestTheScoreIsUsable:
    def test_score_is_well_formed(self, report):
        assert 0.0 <= report.soft_score <= 1.0

    def test_something_was_actually_scored(self, report):
        scored = [c for c in report.results
                  if c.gate is Gate.SOFT and c.weight > 0
                  and c.verdict is not Verdict.ABSTAIN]
        if any(c.id.startswith("A5") for c in report.hard_failures):
            pytest.skip("run has no trajectory")
        assert scored, "every scored check abstained, so the score is empty"

